import "dotenv/config";
import { z } from "zod";

export const env = z.object({
  RPC_URL: z.string().url(),
}).parse(process.env);

export async function getChainData(address: string): Promise<Result<Data>> {
  if (!isAddress(address)) return { ok: false, error: "Bad address" };
  const [block, balance] = await Promise.all([
    provider.getBlockNumber(), provider.getBalance(address as Address),
  ]);
  return { ok: true, value: { block, balance } };
}

async function main() {
  const address = process.argv[2];
  const result = await getChainData(address);
  if (!result.ok) { console.error(result.error); process.exit(1); }
  console.log(result.value);
}

main().catch((err) => { console.error(err); process.exit(1); });
